const productData = await browserjs(tabId, () => {
  // Select product items or grid items
  const items = [];
  const productCards = document.querySelectorAll('li.product-grid-product, li[data-productid], .product-grid-product-info');

  // Also iterate through product info blocks
  const productInfos = document.querySelectorAll('.product-grid-product-info');
  productInfos.forEach(info => {
    const nameEl = info.querySelector('.product-grid-product-info__name, h3, h2, a');
    const priceEl = info.querySelector('.money-amount, .price, .product-grid-product-info__price');
    const name = nameEl ? nameEl.textContent.trim() : '';
    const price = priceEl ? priceEl.textContent.trim() : '';
    if (name) {
      items.push({ name, price });
    }
  });

  // If items empty, let's parse from the list items in the product grid
  if (items.length === 0) {
    const gridItems = document.querySelectorAll('ul.product-grid__product-list > li');
    gridItems.forEach(li => {
      const name = li.querySelector('h3, h2, .product-grid-product-info__name')?.textContent.trim();
      const price = li.querySelector('.price, .money-amount')?.textContent.trim();
      const link = li.querySelector('a')?.href;
      if (name) {
        items.push({ name, price, link });
      }
    });
  }

  return items;
});

