const finalCheck = await browserjs(tabId, () => {
  const cards = document.querySelectorAll('li.product-grid-product, li[data-productid]');
  const uniqueItems = new Map();
  cards.forEach(card => {
    const name = card.querySelector('.product-grid-product-info__name, h3, h2')?.textContent.trim();
    const price = card.querySelector('.money-amount, .price, .product-grid-product-info__price')?.textContent.trim();
    const link = card.querySelector('a')?.href;
    if (name && link && !uniqueItems.has(link)) {
      uniqueItems.set(link, { name, price, link });
    }
  });
  return Array.from(uniqueItems.values());
});

